#include <stdio.h>

int bowl[7] = {2, 24, 44, 64, 84, 104, 124};

/* 砍一半：每趟先看正中间那一只，答「比了几次」；没找到答负数 */
int half_find(int target) {
    int lo = 0;
    int hi = 6;
    int tries = 0;

    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        tries++;
        if (bowl[mid] == target) {
            return tries;
        } else if (bowl[mid] < target) {
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }
    return -tries;
}

int main(void) {
    int want = 124;
    int n = half_find(want);
    if (n < 0) {
        printf("找 %d：没找到\n", want);
    } else {
        printf("找 %d：比了 %d 次\n", want, n);
    }
    return 0;
}

